ego-browser nodejs <<'EOF'
const task = await taskSpace('f10-arena-gatefix')
const p1 = task.page('p1')
await p1.goto('https://arena.ai/agent')
await new Promise(r => setTimeout(r, 4000))

// focus composer and insert text via execCommand (tiptap workaround)
await p1.evaluate(() => {
  const ed = document.querySelector('[contenteditable="true"]')
  if (!ed) throw new Error('no contenteditable found')
  ed.focus()
  const prompt = `本任务只涉及 dd2003-460/hermes-workspace-zero 仓库的 arena/f10-r3-gate-fix 分支，忽略历史中其他仓库的消息。\n\n任务: 补齐 F10-R3 调研门禁缺口 (A域 4/5→5/5, D域 2/3→3/3)。\n\n步骤:\n1. git checkout arena/f10-r3-gate-fix && git pull\n2. 读 loop-artifacts/stages/05/r6/research/gate-fix-taskcard.md 了解具体要求\n3. A域: 在 research/A.md §2 追加第5条独立团队证据 (候选: Challet & Bouchaud trader ecology / order book ABM 类), 需不同作者团队 + URL + 日期 + ≤8行摘要\n4. D域: 在 research/D.md §2 追加第3条独立团队证据 (候选: Griffin & Shiller JFE 2013 forced selling / 其他已发表 forced flow 实证), 同上要求\n5. 更新 receipts.json: A.independent_lines=5 gate=pass, D.independent_lines=3 gate=pass, commit_sha 回填\n6. commit + push 到 arena/f10-r3-gate-fix\n\n交付: 修改后的 A.md / D.md / receipts.json, push 后报告 commit sha。`
  document.execCommand('insertText', false, prompt)
  return ed.innerText.length
}).then(len => console.log('inserted len:', len))

await new Promise(r => setTimeout(r, 2000))
// verify length > 50 before sending
const len = await p1.evaluate(() => document.querySelector('[contenteditable="true"]').innerText.length)
console.log('composer len:', len)
if (len < 50) { console.log('ABORT: too short'); await task.finish({keep:[]}); process.exit(1) }

// find and click Send button
const s = await p1.snapshot()
const sendIdx = s.indexOf('Send')
console.log('send context:', s.substring(Math.max(0,sendIdx-100), sendIdx+100))
await task.finish({ keep: [] })
EOF

